-- D-31 Water & Utilities: FSQM-033 Water Supply Program and FRM-915 Annual Water Supply Verification, both DRAFT.
--
-- Eleven Non-Compliant findings, 11.5.1.1 to 11.5.3.2 (11.5.3.3 was left unscored and is covered too).
-- FSQM-033 is reserved in the remediation workbook; the workbook leaves the log as FRM-9xx and FRM-915 is
-- the next free number after FRM-914.
--
-- Owner's answers, 2026-09-29: City of Sanford water; one backflow preventer for the whole complex, tester
-- unknown; meters recently separated per unit; one water heater, outside; the pot washer heats its own
-- water; never a boil-water notice; will sign up for the city's alerts and test once a year.
--
-- FRM-915 is ONE ENTRY PER YEAR holding all three annual items (city report, site water test, complex
-- backflow report). One record, not three, because verification_schedule derives last-completed from the
-- latest submitted entry of the evidence form and cannot tell entry types apart: at issue both 'planned'
-- rows (backflow_testing, water_analysis) point at FRM-915, which is only honest if every entry holds both.
-- A supply incident is NOT an FRM-915 entry - it would reset both annual due dates - it goes on FRM-007.
-- Owner, 2026-09-29: no monthly hot water or backflow check - backflow is tested once a year (landlord), and a
-- sink without hot water is reported when found. FSQM-033 adds no scheduled check to FRM-913.

begin;

do $guard$
begin
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-033', 'FRM-915')) then
    raise exception 'FSQM-033 or FRM-915 already exists.';
  end if;
  if (select count(*) from public.sop_documents
       where sop_number in ('FRM-007', 'FRM-206', 'FRM-702', 'FRM-903', 'FSQM-009', 'FSQM-013', 'FSQM-014', 'FSQM-018', 'SOP-905') and status = 'active') <> 9 then
    raise exception 'a document D-31 names is missing or not active.';
  end if;
end $guard$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values
  ('FSQM-033', 'Water Supply Program', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '11.5.1.1, 11.5.1.2, 11.5.1.3, 11.5.1.4, 11.5.1.5, 11.5.1.6, 11.5.2.1, 11.5.2.2, 11.5.2.3, 11.5.3.1, 11.5.3.2, 11.5.3.3',
   true, $q${"purpose": "This program states where the site's water comes from, how it is kept safe inside the building, how it is checked, and what is done when the supply is contaminated or lost, so that water never becomes a source of contamination for product.", "scope": "All water used in units 415 and 425: as an ingredient, for handwashing, and for cleaning food-contact surfaces and equipment. It covers the supply from the City of Sanford's main to every outlet in the building.", "definitions": "Potable water: water safe to drink, meeting the drinking water standards below.\nBackflow: water flowing the wrong way, from equipment, a hose or a sink back into the supply pipes, carrying whatever it has touched.\nBackflow preventer: a valve assembly that stops backflow. An air gap - open space between the end of a tap and the water below it - does the same job.\nBoil-water notice: a notice from the city that the supply may be unsafe and must not be used without boiling.", "responsibility": "SQF Practitioner - owns this program; keeps the city's annual Water Quality Report, the backflow test report and the annual water test on FRM-915; is signed up to the city's alerts; decides on product and restart when the supply is compromised.\nProduction staff - use water only from the taps shown on the schematic; keep hose ends out of sinks, buckets and drains; stop and report water that looks, smells or tastes wrong, or taps with no hot water.\nLandlord - owns the complex's main backflow preventer and has it tested each year.", "procedure": ["The supply", "• Water is supplied by the City of Sanford public water system (PWS 3590205). There is no well, no storage tank and no treatment on site; water is used as the city delivers it (SQF 11.5.1.1).", "• The city tests its water continuously and publishes an Annual Water Quality Report. Each year's report is attached to that year's FRM-915 entry as the evidence that the source is potable (SQF 11.5.1.1, 11.5.3.1).", "• The standard the water must meet is the US EPA National Primary Drinking Water Regulations as adopted in Florida (Chapter 62-550, F.A.C.). For the site's own test, total coliform and E. coli must both be absent in 100 mL (SQF 11.5.3.1).", "• Water is used here as an ingredient, for handwashing, and for cleaning food-contact surfaces and equipment. All three take potable water from the same supply (SQF 11.5.3.1 ii, iv, v).", "• Water is not used here to wash, thaw or convey food, no ice is made or used, and no steam touches food - the oven's steam system is not connected to the water supply and is not used. So 11.5.3.1 i, iii, vi and vii do not arise. The kettle's jacket is sealed; the water in it never touches food.", "• The water schematic attached to this program shows the city main, the complex's backflow preventer, the unit's meter, the water heater, every outlet and machine connection, and the sample tap. It is redrawn whenever the plumbing changes (SQF 11.5.1.1).", "Hot and cold water", "• One water heater, outside the building, supplies hot water to the three handwash stations, the 3-compartment sink and the wash basin in the dry room. Every one of them also has cold water (SQF 11.5.1.3).", "• The pot and pan washer heats its own water for its sanitizing rinse, as SOP-905 describes (SQF 11.5.1.3).", "• Staff use these sinks every production day, so a lack of hot water shows at once. Anyone who finds a handwash station or sink without hot water tells the Production Supervisor, and it is fixed before it is used for handwashing or cleaning. There is no separate scheduled hot water check (SQF 11.5.1.3).", "Keeping the supply clean inside the building", "• The backflow preventer beside the water meter protects the units' drinking-water supply. It is owned by the landlord. The City of Sanford requires it to be tested each year by a certified tester. Each year the SQF Practitioner gets a copy of the latest test report from the landlord, or from the city if the landlord does not have it, and attaches it to FRM-915 (SQF 11.5.1.4).", "• Inside the unit, the only backflow devices are the vacuum breakers on the hose taps (below); the device at the meter protects the city, not the taps inside the unit. Every sink and basin tap discharges above the rim of its sink, which leaves an air gap, so water in the sink cannot be drawn back into the tap (SQF 11.5.1.4, 11.5.1.5 iii).", "• Every tap a hose is attached to has a hose-bib vacuum breaker fitted. Hoses are stored off the floor, and a hose end is never left in a sink, bucket or drain (SQF 11.5.1.5 iii).", "• Detergent and sanitizer are measured into a sink or bucket already filled with water. The tap is never below the water surface.", "• Work on the supply pipes is done by a licensed plumber. Afterwards every affected tap is run before use, and the schematic is updated (SQF 11.5.1.4).", "Non-potable water, storage and treatment", "• The complex's fire sprinkler system is the only non-potable water on the site. It has its own line from the city main, separated from it by a double check detector assembly beside the road, and has no outlet anywhere water is used for food, handwashing or cleaning (SQF 11.5.1.5 i).", "• No other non-potable water is used. If a non-potable line is ever added, it is labelled along its length and at every outlet, and is never connected to the potable supply (SQF 11.5.1.5 i, ii).", "• No water is stored on site. There is no tank or cistern; the water heater is part of the supply pipes, not storage (SQF 11.5.1.6).", "• No water is treated on site - no softener, filter, reverse osmosis or chlorination. The treatment clauses 11.5.2.1 to 11.5.2.3 therefore do not apply. If treatment equipment is ever fitted, this program is revised first to say how it is monitored (SQF 11.5.2.1, 11.5.2.2, 11.5.2.3).", "Testing the water", "• At least once a year, a sample is taken from the 3-compartment sink faucet on the production floor and tested for total coliform and E. coli (SQF 11.5.3.2).", "• The test is done by a laboratory certified by the Florida Department of Health for drinking water, using an EPA-approved method. The laboratory is listed on the Contract Services Register, FRM-206 (SQF 11.5.3.3).", "• The sample is taken exactly as the laboratory instructs, in its sterile bottle, and delivered within the time it allows.", "• Once a year is enough because the supply is the city's treated water, the pipe run is short, and nothing is stored or treated on site. An extra sample is taken when production restarts after a boil-water notice or after work on the supply pipes (SQF 11.5.3.2).", "• The laboratory report is attached to FRM-915 and reviewed by the SQF Practitioner. Coliform or E. coli present is a contaminated supply, handled as below.", "When the supply is contaminated or lost", "• The site is signed up to the City of Sanford's alerts, so it learns of a boil-water notice when it is issued (SQF 11.5.1.2).", "• On a boil-water notice, a positive test, a loss of supply, or water that looks, smells or tastes wrong, production stops. Tap water is not used for ingredients, cleaning or handwashing until the problem is over (SQF 11.5.1.2).", "• Product made, or made on equipment cleaned, with the affected water since the problem began is held under FSQM-018 on FRM-702, and the SQF Practitioner decides what happens to it (SQF 11.5.1.2).", "• Production restarts only after the city lifts the notice, or a repeat test is clear. Every hot and cold tap is run for at least five minutes, the pot and pan washer is drained and refilled, and food-contact surfaces are cleaned and sanitized and released on FRM-903 (SQF 11.5.1.2).", "• The event is recorded on FRM-007 under FSQM-009: what happened, what was held and how production restarted.", "Review", "• This program is reviewed each year, and whenever the plumbing, the equipment that uses water, or the city's requirements change. FSQM-028's water risk is revisited when it issues."], "form_references": "FRM-915 - Annual Water Supply Verification\nFRM-903 - Daily Sanitation, Pre-Operation & Release Record (release after a supply problem)\nFRM-206 - Contract Services Register (the testing laboratory)\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "records": "• FRM-915, once a year: the city's Annual Water Quality Report, the site's water test result and the test report for the backflow preventer at the meter, each attached\n• The water schematic, attached to this program\n• FRM-007, FRM-702 and FRM-903 for any supply problem", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 11.5.1.1 to 11.5.1.6 (Water Supply), 11.5.2.1 to 11.5.2.3 (Water Treatment), 11.5.3.1 to 11.5.3.3 (Water Quality).\nUS EPA National Primary Drinking Water Regulations (40 CFR 141); Florida Chapter 62-550, F.A.C.\nCity of Sanford Annual Water Quality Report and Cross Connection Control requirements.\nFSQM-013 Module 11 Applicability & Exemption Analysis - water used as delivered, no treatment.\nFSQM-018 Non-Conforming Product and Equipment - product held after a supply problem.\nFSQM-009 CAPA Program - recording a supply problem.\nSOP-905 - the pot and pan washer's own heated rinse.", "revision_history": "New - 2026-09-29 - DRAFT under D-31, for the eleven Non-Compliant findings against 11.5.1.1 to 11.5.3.2 (and 11.5.3.3, which the gap assessment left unscored).\n\nWHAT THE SITE HAS (owner, 2026-09-29): City of Sanford water; one large backflow preventer serving the whole complex, tester not known - the owner's photo shows it is the FIRE LINE's double check detector assembly (red, supervised gate valves, bypass meter, beside a hydrant), with an annual test tag, and the units' drinking-water supply has its own backflow preventer beside the meter - the only backflow device; there was none on any equipment or hose inside the unit, and the owner will fit hose-bib vacuum breakers on every tap a hose is used on; the units' meters were recently separated; one water heater, outside; the pot and pan washer heats its own water; no boil-water notice has ever been issued here; no ice machine, no storage tank, no filter or softener; the oven's steam system is not connected and is not used. The annual sample is taken at the 3-compartment sink faucet on the production floor. The site will sign up to the city's alerts and test its water once a year. No monthly hot water or backflow check (owner: overkill) - backflow is tested once a year, and a sink without hot water is reported when found.\n\nNEW WITH THIS PROGRAM: the annual water test (the site has done no analysis until now - FSQM-014), getting the complex's backflow test report each year, and a written contingency plan. At issue, the two 'planned' rows on the verification schedule - backflow testing and water analysis - become active against FRM-915.\n\nTO CONFIRM BEFORE ISSUE: (1) the hose-bib vacuum breakers fitted, and whether the pot and pan washer's water fill has a built-in air gap or vacuum breaker (its data plate or manual); (2) the water schematic, to draw and attach; (3) the laboratory, to choose and list on FRM-206; (4) a copy of the latest test report for the backflow preventer at the meter, and the fire line's, from the landlord."}$q$::jsonb),
  ('FRM-915', 'Annual Water Supply Verification', 'form', 'Module 11', 'draft', 'New',
   '11.5.1.1, 11.5.1.4, 11.5.3.1, 11.5.3.2', true, jsonb_build_object('form_schema', $b${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": false, "requireVerification": true, "instanceTitleTemplate": "{check_year} - water supply verification"}, "sections": [{"id": "year", "title": "1. The year", "fields": [{"id": "how_this_works", "type": "info", "label": "One entry per year", "text": "Start this entry when the first of the three items below comes in, and submit it once all three are here. Attach each report to this entry."}, {"id": "check_year", "type": "text", "label": "Year", "width": "third", "required": true, "showInList": true}]}, {"id": "city", "title": "2. City of Sanford Annual Water Quality Report", "fields": [{"id": "ccr_year", "type": "text", "label": "Report for year", "width": "third", "required": true}, {"id": "ccr_violations", "type": "select", "label": "Violations listed in the report", "width": "third", "required": true, "options": ["None", "Yes - described below"]}, {"id": "ccr_notes", "type": "textarea", "label": "Notes", "help": "Any violation, and whether it affects the site"}]}, {"id": "test", "title": "3. Site water test", "fields": [{"id": "sample_date", "type": "date", "label": "Sample taken", "width": "third", "required": true}, {"id": "sample_point", "type": "text", "label": "Tap sampled", "width": "third", "required": true, "help": "As marked on the water schematic"}, {"id": "laboratory", "type": "text", "label": "Laboratory", "width": "third", "required": true}, {"id": "coliform", "type": "select", "label": "Total coliform", "width": "third", "required": true, "options": ["Absent", "Present"]}, {"id": "ecoli", "type": "select", "label": "E. coli", "width": "third", "required": true, "options": ["Absent", "Present"]}, {"id": "test_result", "type": "select", "label": "Result", "width": "third", "required": true, "showInList": true, "options": ["Pass - both absent", "Fail - handled as a contaminated supply"]}, {"id": "test_action", "type": "textarea", "label": "If failed: what was done", "help": "Production stopped, product held (FRM-702 tag), repeat test, CAPA number"}]}, {"id": "backflow", "title": "4. Backflow", "fields": [{"id": "bf_test_date", "type": "date", "label": "Backflow preventer at the meter tested on", "width": "third", "required": true}, {"id": "bf_tester", "type": "text", "label": "Tested by", "width": "third", "required": true}, {"id": "bf_result", "type": "select", "label": "Result", "width": "third", "required": true, "showInList": true, "options": ["Passed", "Failed - repaired and passed on retest", "Failed - not yet repaired"]}, {"id": "bf_unit_devices", "type": "select", "label": "Taps and hoses inside the unit", "required": true, "help": "Every sink tap still above the rim; a vacuum breaker on every hose tap; no hose end left in a sink, bucket or drain", "options": ["As the program requires", "Problem - described below"]}, {"id": "bf_notes", "type": "textarea", "label": "Notes"}]}, {"id": "schematic", "title": "5. Schematic", "fields": [{"id": "schematic_current", "type": "select", "label": "Water schematic", "required": true, "options": ["Still matches the plumbing", "Plumbing changed - schematic redrawn and re-attached to FSQM-033"]}]}, {"id": "sign", "title": "6. Sign-off", "fields": [{"id": "recorded_by", "type": "signature", "label": "Recorded by", "role": "filler", "required": true, "statement": "The reports attached to this entry are the ones summarised above."}, {"id": "reviewed_by", "type": "signature", "label": "Reviewed by the SQF Practitioner", "role": "verifier", "required": true, "statement": "I have reviewed the reports and the water supply remains fit for use."}]}]}$b$::jsonb));

do $verify$
declare p jsonb; fs jsonb;
begin
  select content->'procedure' into p from public.sop_documents where sop_number = 'FSQM-033';
  if jsonb_array_length(p) <> 36 then
    raise exception 'FSQM-033 procedure is % lines, expected 36.', jsonb_array_length(p);
  end if;
  if (select count(*) from unnest(array['11.5.1.1', '11.5.1.2', '11.5.1.3', '11.5.1.4', '11.5.1.5', '11.5.1.6', '11.5.2.1', '11.5.2.2', '11.5.2.3', '11.5.3.1', '11.5.3.2', '11.5.3.3']) c where p::text like '%' || c || '%') <> 12 then
    raise exception 'FSQM-033 does not cite every clause of 11.5.1 to 11.5.3.';
  end if;
  select content->'form_schema' into fs from public.sop_documents where sop_number = 'FRM-915';
  if (select count(*) from jsonb_array_elements(fs->'sections') s, jsonb_array_elements(s->'fields') f
       where f->>'type' = 'signature' and f->>'role' = 'verifier') <> 1 then
    raise exception 'FRM-915 must carry exactly one verifier signature.';
  end if;
end $verify$;

commit;
